import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
import {aqueousCases,aqueousProducts} from './aqueous-models.js?v=20261023-physicscomplete01';
const sub=s=>s.replace(/2/g,'₂');
const text=(x,y,s,size=13,c='#f8f6f2')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-size="${size}" font-family="sans-serif">${s}</text>`;
export function showAqueous(kind='water',t=aqueousCases[0],reveal=false){
 if(['plan','evidence','evaluate'].includes(kind)){
 const lines=kind==='plan'?['Change: chloride → sulfate','Keep: inert electrodes and conditions','Predict: products at each electrode']:kind==='evaluate'?['Unexpected sulfate result: bleaching','Previous trial: chloride; no cleaning','Next: test an alternative explanation']:['Copper chloride: brown deposit / bleaching','Copper sulfate: brown deposit / relights','Data are illustrative, not live measurements'];
 const table=kind==='evidence'?'<table class="aqueous-observations"><caption>Teacher’s observations</caption><thead><tr><th>Solution</th><th>Cathode</th><th>Anode gas test</th></tr></thead><tbody><tr><th>Copper chloride</th><td>Reddish-brown deposit</td><td>Bleaches damp litmus</td></tr><tr><th>Copper sulfate</th><td>Reddish-brown deposit</td><td>Relights glowing splint</td></tr></tbody></table>':`<svg class="lab-svg" viewBox="0 0 440 250" role="img" aria-label="${lines.join('. ')}"><path d="M70 65H370 M70 130H370 M70 195H370" stroke="#b7c8d6" stroke-opacity=".3"/>${lines.map((s,i)=>text(220,48+i*65,s,13)).join('')}</svg>`;
 renderDiagram(kind==='plan'?'Plan the comparison':kind==='evidence'?'Observation → interpretation':'Test the explanation','Aqueous electrolysis · inert electrodes',table,'PRACTICAL PREPARATION · ILLUSTRATIVE EVIDENCE');return;
 }
 const p=aqueousProducts(t),c=reveal?sub(p.cathode):'?',a=reveal?sub(p.anode):'?';
 const ion=(x,y,label,colour)=>`<circle cx="${x}" cy="${y}" r="25" fill="${colour}"/>${text(x,y+5,label,13,'#182e44')}`;
 renderDiagram('Which ions are discharged?',t.name,`<svg class="lab-svg" viewBox="0 0 440 285" role="img" aria-label="${t.name}. Cathode negative; anode positive. Salt ions ${t.ions.join(' and ')}, with H+ and OH− from water. ${reveal?'Products: '+sub(p.cathode)+' and '+sub(p.anode):'Products hidden until prediction is checked.'}"><defs><linearGradient id="aqFill" x2="0" y2="1"><stop stop-color="#3b566a"/><stop offset="1" stop-color="#182e44"/></linearGradient></defs><path d="M48 85V240H392V85" fill="url(#aqFill)" stroke="#b7c8d6" stroke-width="2"/><path d="M82 74V202 M358 74V202" stroke="#b7c8d6" stroke-width="12"/>${text(84,25,'− Cathode')}${text(356,25,'+ Anode')}${text(84,56,c,21)}${text(356,56,a,21)}<path d="M82 74V72H185 M255 72H358V74" fill="none" stroke="#b7c8d6" stroke-width="2"/><rect x="185" y="62" width="70" height="22" rx="5" fill="#182e44" stroke="#b7c8d6"/>${text(220,77,'DC supply',10)}${ion(156,135,t.ions[0],'#ed8b78')}${ion(280,135,t.ions[1],'#b7c8d6')}${ion(156,201,'H⁺','#ed8b78')}${ion(280,201,'OH⁻','#b7c8d6')}<path d="M124 135H98 M124 201H98 M312 135H342 M312 201H342" stroke="#f8f6f2" stroke-width="1.5"/><path d="M103 131l-5 4 5 4 M103 197l-5 4 5 4 M337 131l5 4-5 4 M337 197l5 4-5 4" fill="none" stroke="#f8f6f2"/>${text(220,268,'Water adds competing ions',12)}</svg><p class="diagram-caption">AQA GCSE product model · one dissolved compound · inert electrodes. Ion numbers, sizes and paths are symbolic; real conditions can alter products.</p>`,'AQUEOUS PRODUCT MODEL · NOT TO SCALE');
}
